"""V21 Worker fixture: cycles produced by the real Python producer from the synthetic chains of tests/fixtures/v21_put_chains.py.

Regenerate with `python -m tests.fixtures.v21_worker_cases` (writes cloud/test/fixtures/v21-three-strategies.json). Synthetic prices only.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path
from unittest import mock

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "scripts"))

import build_market_quotes_options as builder  # noqa: E402
from tests.fixtures import v21_put_chains as chains  # noqa: E402

FIXTURE_PATH = ROOT / "cloud" / "test" / "fixtures" / "v21-three-strategies.json"


def generate_fixture_document() -> dict:
    with mock.patch.dict(sys.modules, {"yfinance": chains.yahoo_module(chains.yahoo_chain())}):
        full = builder.us_options("AAA", chains.SPOT, chains.TODAY, chains.STAMP)["monthly"]
    one_sided_calls = [(k, None, a) for k, _, a in chains.CALLS]
    with mock.patch.dict(sys.modules, {"yfinance": chains.yahoo_module(chains.yahoo_chain(calls=one_sided_calls))}):
        ccless = builder.us_options("AAA", chains.SPOT, chains.TODAY, chains.STAMP)["monthly"]
    with mock.patch.object(builder, "http_json", lambda url: {"data": {"instrumentListing": {"rows": chains.nordic_rows()}}}):
        nordic = builder.nordic_options("SIVE.ST", "SIVE", chains.SPOT, chains.TODAY, chains.STAMP, "TX1", spot_currency="SEK")["monthly"]
    # Retained scenario grouping; wide/one-sided cases may now contain qualified recommendations, not just observations.
    observations = {}
    wide_calls = [(k, 0.01, 0.50) for k, _, _ in chains.CALLS]
    wide_puts = [(k, 0.01, 0.50) for k, _, _ in chains.PUTS]
    for name, calls, puts in (
        ("wide_all", wide_calls, wide_puts),
        ("wide_calls", wide_calls, chains.PUTS),
        ("no_two_sided_put", wide_calls, [(k, None, a) for k, _, a in chains.PUTS]),
        ("absent_puts", wide_calls, []),
        ("unknown_puts", wide_calls, None),
        ("delta_call", [(104.0, 1.83, 1.87)], chains.PUTS),
        ("collar_only", [(107.0, 1.05, 1.09)], [(92.0, 0.59, 0.63)]),
    ):
        with mock.patch.dict(sys.modules, {"yfinance": chains.yahoo_module(chains.yahoo_chain(calls=calls, puts=puts))}):
            observations[name] = builder.us_options("AAA", chains.SPOT, chains.TODAY, chains.STAMP)["monthly"]
    return {"note": "synthetic; generated by tests/fixtures/v21_worker_cases.py", "stamp": chains.STAMP, "cases": {
        "yahoo_monthly_full": full, "yahoo_monthly_no_covered_call": ccless, "nordic_monthly_sek": nordic},
        "observations": observations}


def write_fixture(path: Path | None = None) -> Path:
    target = path or FIXTURE_PATH
    target.write_bytes((json.dumps(generate_fixture_document(), indent=1, ensure_ascii=False, sort_keys=True) + "\n").encode("utf-8"))
    return target


if __name__ == "__main__":
    out = write_fixture()
    print(f"V21 worker fixture written: {out} ({out.stat().st_size} bytes)")
